const point = Object.freeze({ x: 1 });
const plain = { x: 1 };
const label = "total";

function attempt(write) {
  try {
    write();
    return "ok";
  } catch (error) {
    return error.name;
  }
}

console.log(attempt(() => { point.x = 10; }));
console.log(attempt(() => { plain.x = 10; }));
console.log(attempt(() => { label.unit = "kg"; }));
console.log(point.x + plain.x);
